command:
$ErrorActionPreference = "Stop"
git fetch origin main work/large-folder-resident-window --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "d395db0f40b2a3863be4216ba1644f46f42c8dc0") { throw "main moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }

git checkout -B work/large-folder-resident-window origin/work/large-folder-resident-window
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
if ((git rev-parse HEAD).Trim() -ne "37d4cc023777c67a963710efd2e17ee7125a7cae") { throw "candidate mismatch" }

cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }

if (!(Test-Path -LiteralPath "out\winui\Release\flyExplorer.exe")) {
  throw "accepted baseline Release binary missing"
}
python -X utf8 tests\winui\test_large_owned_folder_gui.py --items 2300 --configuration Release --resident-window-evidence before
if ($LASTEXITCODE -ne 0) { throw "matched BEFORE resident-window GUI capture failed" }

cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "Release build failed" }

$env:FLY_M16_CONFIG = "Release"
python -X utf8 tests\winui\helper\test_process_isolation.py
if ($LASTEXITCODE -ne 0) { throw "focused helper process-isolation test failed" }

python -X utf8 tests\winui\test_large_owned_folder_gui.py --items 2300 --configuration Release --resident-window-evidence after
if ($LASTEXITCODE -ne 0) { throw "resident-window GUI/visual acceptance failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "LARGE_FOLDER_RESIDENT_WINDOW_ACCEPTANCE_PASS"
